  sub_county.id,
  region.id
FROM facility_seed AS seed
LEFT JOIN districts AS district
  ON district.name = seed.district_name
LEFT JOIN sub_counties AS sub_county
  ON sub_county.name = seed.sub_county_name
 AND sub_county.district_id = district.id
LEFT JOIN regions AS region
  ON region.name = seed.region_name
ON CONFLICT (name, district_id) DO UPDATE SET
  sub_county_id = EXCLUDED.sub_county_id,
  region_id = EXCLUDED.region_id,
  updated_at = now();
